with ins as (insert into public.artist_aliases (artist_slug,alias,kind,source_url) select x.s,x.a,x.k,x.u from json_to_recordset('[{"s":"electroson","a":"Zionwolf","k":"also_known_as","u":"https://www.thewildcity.com/news/19969-magnetic-fields-announces-additions-to-its-2022-edition"}]'::json) as x(s text,a text,k text,u text) join public.artists a on a.slug=x.s on conflict (artist_slug,alias) do nothing returning 1) select count(*) from ins;